package local.civic.home;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;

final class ThemedDialogs {
 static final class Builder extends AlertDialog.Builder {
  final Activity activity;CharSequence title;CharSequence[] choices;int selected=-1;DialogInterface.OnClickListener choose;
  Builder(Activity a){super(a);activity=a;}
  @Override public Builder setTitle(CharSequence s){title=s;super.setTitle(s);return this;}
  @Override public Builder setItems(CharSequence[] s,DialogInterface.OnClickListener l){choices=s;choose=l;return this;}
  @Override public Builder setSingleChoiceItems(CharSequence[] s,int n,DialogInterface.OnClickListener l){choices=s;selected=n;choose=l;return this;}
  @Override public AlertDialog create(){if(choices!=null)return choiceDialog();AlertDialog dialog=super.create();dialog.setOnShowListener(d->style(dialog));return dialog;}
  @Override public AlertDialog show(){AlertDialog dialog=create();dialog.show();style(dialog);return dialog;}
  AlertDialog choiceDialog(){UiKit ui=new UiKit(activity);LinearLayout root=ui.column();root.setPadding(ui.dp(16),ui.dp(8),ui.dp(16),ui.dp(12));root.setBackground(new GlassDrawable(ui.t.background,ui.dp(16),ui.t.cardBorder));LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);TextView back=ui.text("‹",28,ui.t.textPrimary);back.setGravity(Gravity.CENTER);header.addView(back,new LinearLayout.LayoutParams(ui.dp(56),ui.dp(56)));TextView heading=ui.text(title==null?"Select an option":title.toString(),20,ui.t.textPrimary);heading.setTypeface(Typeface.DEFAULT,Typeface.BOLD);header.addView(heading,new LinearLayout.LayoutParams(0,ui.dp(56),1));root.addView(header);ListView list=new ListView(activity);list.setDivider(null);int available=(int)(activity.getResources().getDisplayMetrics().heightPixels/activity.getResources().getDisplayMetrics().density)-120;root.addView(list,new LinearLayout.LayoutParams(-1,ui.dp(Math.min(Math.max(56,available),choices.length*64))));AlertDialog dialog=new AlertDialog.Builder(activity).setView(root).create();back.setOnClickListener(v->dialog.dismiss());list.setAdapter(new BaseAdapter(){public int getCount(){return choices.length;}public Object getItem(int n){return choices[n];}public long getItemId(int n){return n;}public View getView(int n,View recycled,ViewGroup parent){LinearLayout row=recycled instanceof LinearLayout?(LinearLayout)recycled:ui.valueRow("","",null);((TextView)row.getChildAt(0)).setText(choices[n]);TextView mark=(TextView)row.getChildAt(1);mark.setText(n==selected?"✓":"");mark.setTextColor(ui.t.accent);mark.setTag(UiKit.Role.ACCENT);row.setBackground(new GlassDrawable(ui.t.card,ui.dp(10),n==selected?ui.t.accent:ui.t.cardBorder));AbsListView.LayoutParams p=new AbsListView.LayoutParams(-1,ui.dp(64));row.setLayoutParams(p);return row;}});list.setOnItemClickListener((p,v,n,id)->{dialog.dismiss();if(choose!=null)choose.onClick(dialog,n);});return dialog;}
  void style(AlertDialog d){ThemeTokens t=ThemeTokens.get(activity);Window w=d.getWindow();if(w==null)return;GradientDrawable bg=new GradientDrawable();bg.setColor(t.card);bg.setCornerRadius(new UiKit(activity).dp(16));w.setBackgroundDrawable(bg);w.getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);int width=Math.min(activity.getResources().getDisplayMetrics().widthPixels-new UiKit(activity).dp(40),new UiKit(activity).dp(680));w.setLayout(width,WindowManager.LayoutParams.WRAP_CONTENT);tint(w.getDecorView(),t);for(int id:new int[]{DialogInterface.BUTTON_POSITIVE,DialogInterface.BUTTON_NEGATIVE,DialogInterface.BUTTON_NEUTRAL}){Button b=d.getButton(id);if(b!=null){b.setTextColor(t.accent);b.setMinHeight(new UiKit(activity).dp(56));}}}
  void tint(View v,ThemeTokens t){if(v instanceof TextView){Object role=v.getTag();((TextView)v).setTextColor(role==UiKit.Role.ACCENT?t.accent:role==UiKit.Role.SECONDARY?t.textSecondary:t.textPrimary);if(v instanceof EditText)((EditText)v).setBackgroundTintList(android.content.res.ColorStateList.valueOf(t.accent));}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)tint(g.getChildAt(n),t);}}
 }
}
